; // sw x5,24(x31)\n            10'h04c : o_inst = 32'h4041d2b3; // sra x5,x3,x4\n            10'h050 : o_inst = 32'h005fae23; // sw x5,28(x31)\n            10'h054 : o_inst = 32'h01e21293; // slli x5,x4,0x1e\n            10'h058 : o_inst = 32'h025fa023; // sw x5,32(x31)\n            10'h05c : o_inst = 32'h01c1d293; // srli x5,x3,0x1c\n            10'h060 : o_inst = 32'h025fa223; // sw x5,36(x31)\n            10'h064 : o_inst = 32'h4011d293; // srai x5,x3,0x1\n            10'h068 : o_inst = 32'h025fa423; // sw x5,40(x31)\n            10'h06c : o_inst = 32'h0030c2b3; // xor x5,x1,x3\n            10'h070 : o_inst = 32'h025fa623; // sw x5,44(x31)\n            10'h074 : o_inst = 32'hfff24293; // xori x5,x4,-1\n            10'h078 : o_inst = 32'h025fa823; // sw x5,48(x31)\n            10'h07c : o_inst = 32'h0040e2b3; // or x5,x1,x4\n            10'h080 : o_inst = 32'h025faa23; // sw x5,52(x31)\n            10'h084 : o_inst = 32'h7f026293; // ori x5,x4,2032\n            10'h088 : o_inst = 32'h025fac23; // sw x5,56(x31)\n            10'h08c : o_inst = 32'h0030f2b3; // and x5,x1,x3\n            10'h090 : o_inst = 32'h025fae23; // sw x5,60(x31)\n            10'h094 : o_inst = 32'h0ff0f293; // andi x5,x1,255\n            10'h098 : o_inst = 32'h045fa023; // sw x5,64(x31)\n            10'h09c : o_inst = 32'h0041a2b3; // slt x5,x3,x4\n            10'h0a0 : o_inst = 32'h045fa223; // sw x5,68(x31)\n            10'h0a4 : o_inst = 32'h0041b2b3; // sltu x5,x3,x4\n            10'h0a8 : o_inst = 32'h045fa423; // sw x5,72(x31)\n            10'h0ac : o_inst = 32'hfff22293; // slti x5,x4,-1\n            10'h0b0 : o_inst = 32'h045fa623; // sw x5,76(x31)\n            10'h0b4 : o_inst = 32'hfff23293; // sltiu x5,x4,-1\n            10'h0b8 : o_inst = 32'h045fa823; // sw x5,80(x31)\n            10'h0bc : o_inst = 32'h02100313; // addi x6,x0,33\n            10'h0c0 : o_inst = 32'h006212b3; // sll x5,x4,x6\n            10'h0c4 : o_inst = 32'h045faa23; // sw x5,84(x31)\n            10'h0c8 : o_in